mapper.update:


  UPDATE ISSUES_RISKS    /* QueryID : com.demo.proworks.iss.updateIss */      
	  SET  
        PJT_ID        = #{pjtId}        
       , NAME          = #{name}          
       , USER_ID       = #{userId}       
       , DUE_DATE      = #{dueDate}      
       , STATUS        = #{status}        
       , PRIORITY      = #{priority}      
       , DESCRIPTION   = #{description}   
       , CREATED_AT    = #{createdAt}    
       , UPDATED_AT    = #{updatedAt}    
       , RESOLVED_DATE = #{resolvedDate} 
       , RESPONSE_PLAN = #{responsePlan} 
       , IS_DELETED    = #{isDeleted}                     
  WHERE   
          ID            = #{id}

mapper.select:
SELECT /* QueryID : com.demo.proworks.iss.selectListIss */ PJT_ID as pjtId, PJT_NAME as pjtName, ID as id, NAME as name, USER_ID as userId, USER_NAME as userName, DUE_DATE as dueDate, STATUS as status, PRIORITY as priority, DESCRIPTION as description, CREATED_AT as createdAt, UPDATED_AT as updatedAt, RESOLVED_DATE as resolvedDate, RESPONSE_PLAN as responsePlan, IS_DELETED as isDeleted FROM ( SELECT S.*, CEIL( (@ROWNUM:=@ROWNUM+1) / #{pageSize} ) AS PAGE FROM ( SELECT ir.ID, ir.PJT_ID, ir.NAME, ir.USER_ID, ir.DUE_DATE, ir.STATUS, ir.PRIORITY, ir.DESCRIPTION, ir.CREATED_AT, ir.UPDATED_AT, ir.RESOLVED_DATE, ir.RESPONSE_PLAN, ir.IS_DELETED, pjt.PJT_NAME as PJT_NAME, u.NAME as USER_NAME FROM ISSUES_RISKS ir LEFT JOIN PJT pjt ON ir.PJT_ID = pjt.PJT_ID LEFT JOIN USERS u ON ir.USER_ID = u.USER_ID WHERE 1=1
AND ir.PJT_ID = #{pjtId}
AND ir.USER_ID = #{userId}
AND ir.IS_DELETED = 'N' ORDER BY ir.CREATED_AT DESC ) S, (SELECT @ROWNUM := 0) TMP ) A WHERE PAGE = #{pageIndex}

SELECT /* QueryID : com.demo.proworks.iss.selectListCountIss */ COUNT(*) totcnt FROM ISSUES_RISKS WHERE 1=1
AND PJT_ID = #{pjtId}
AND USER_ID = #{userId}
AND IS_DELETED = 'N'
